parameters.jsCode:
const input=$input.first().json; const opportunityId=Number(input.opportunity_id); const tier=String(input.routing_tier||'owner');
if(!Number.isSafeInteger(opportunityId)||opportunityId<=0) throw new Error('valid opportunity_id required');
if(!['owner','primary_guard','backup_guard'].includes(tier)) throw new Error('invalid routing tier');
const number=input.owner_number||input.recipient_number||null; if(!input.attempt_id&&!number) throw new Error('recipient number required');
const button_id=`claim:${opportunityId}:${tier}`; const text=[`Nuevo prospecto para ${input.property_title||'una propiedad'}`,`Lead: ${input.lead_name||'Sin nombre'}`,'Tienes 5 minutos desde la entrega confirmada.'].join('\n');
return [{json:{...input,opportunity_id:opportunityId,routing_tier:tier,button_id,text,number,target_agent_id:input.owner_agent_id||input.agent_id||null}}];

